export function conceptBOM(d){return{units:'mm',printedParts:d.parts.map(p=>p.name),purchased:[{item:'Прозрачная E10 3.5 В / 0.2 А / 0.7 Вт',quantity:1,note:'Размеры колбы и положение нити измерить до печати.'},{item:'Голый двухвыводный E10 + подготовленная FR4 плата',quantity:1,pcb:[18,26,1.6],socketNominal:[d.service.socketDiameter,d.service.socketHeight],note:'Лампа направлена к стене; патрон находится в передней крышке.'},{item:'Внешний стабилизированный БП 3.5 В DC ≥0.3 А',quantity:1,note:'Батарейный блок не входит в эту версию; напрямую к USB5В не подключать.'},{item:'M3×16 + гайка M3',quantity:4,use:'Задняя плита.'},{item:'M2×4',quantity:4,use:'Прижимные лапки круглой оболочки.'},{item:'M2×6',quantity:2,use:'Прижим входного кабеля.'},{item:'M2×4 + шайба0.5мм',quantity:2,use:'Плата E10 в крышке.'},{item:'M2×8 + шайба0.5мм',quantity:2,use:'Съёмная крышка к верхней опоре.'},{item:'Изолированный двухжильный входной кабель + разъём',quantity:1,note:'Оболочка2.8мм, разъём не более8×6мм; проверить ввод и прижим.'},{item:'Два тонких изолированных внутренних проводника',quantity:1,note:'Наружный диаметр каждого≤0.64мм; проложить по тёмной внутренней поверхности и опоре. Ток0.2А, сечение и нагрев проверить.'},{item:'Крепёж к своей стене',quantity:3,note:'Два подвеса и нижний фиксатор; выбирать по материалу стены.'},{item:'Клей для декоративных вставок / мультиматериальная печать',quantity:1,note:'Только золотистые обод и розетка; несущая опора слита с оболочкой.'}],physicalFitTested:false,thermalTested:false};}
export function conceptReadme(d,q){const s=d.service;return `ShadowForge — дизайн №1: полумесяц и мечеть\nРазмеры в мм. ЦИФРОВОЙ ПРОТОТИП, НЕ ПРОИЗВЕДЕННАЯ ПРОБНАЯ ПЕЧАТЬ.\n\nМатовый чёрный диск Ø${d.p.bodySide}, золотистый обод и отдельная розетка. Лампочка E10 направлена к стене. Патрон и плата закреплены в съёмной передней крышке. Круглая чашка ограничивает освещённое поле. Высокая центральная стойка и нижний кронштейн прежней версии удалены. Тонкие верхние опоры действительно объединены с фигурной оболочкой в Blender; в комплекте реальная сварная сетка, а не накладывающиеся тела.\n\nПЕЧАТЬ: единая оболочка с опорой требует поддержек и проверки тонких мест в слайсере. Ширина локального оптического перешейка может быть0.8мм; прочность не испытана. Крышка содержит чашку и внутренние стойки. Обод и розетку печатать отдельно золотистым материалом или выполнить мультиматериальную печать, затем приклеить на лицевую плоскость. Несущие детали не заменять клеевыми точками.\n\nСБОРКА: 1) Вставить гайки задней панели. Провести входной кабель и закрепить прижимом, оставить свободный сервисный шлейф в задней полости. 2) Прикрутить оптическую плиту четырьмяM3×16. 3) Поставить оболочку, ввести прижимные лапки изнутри радиально наружу, закрепитьM2×4. 4) Узел E10 изготовить по шаблонуFR4 18×26×1.6; патрон ${s.socketDiameter}×${s.socketHeight} — номинал. Измерить край патрона→нить ${s.filamentLift}мм. Плата крепится к изнанке передней крышки двумяM2×4 с шайбами0.5мм. Не ставить длинные винты. 5) Тонкие изолированные проводники закрепить по тёмной внутренней части оболочки и вдоль верхней опоры; не проводить отдельную перемычку через светлые отверстия. 6) Установить крышку на дваM2×8 с шайбами0.5мм с тыльной стороны фланца. Ввинтить лампу до установки крышки. Для замены отключить питание, дать остыть, снять светильник со стены и открыть задний доступ к винтам; затем снять крышку вперёд. Прямой доступ отвёрткой через собранные задние плиты отсутствует. 7) Подвесить по шаблону1:1 на два винта и установить нижний фиксатор.\n\nПИТАНИЕ: внешний стабилизированный3.5В DC ≥0.3А. Плюс — центральный контакт E10, минус — резьбовая оболочка. Пайку изолировать. Прямое подключение к5/12/230В недопустимо. Батарейный блок не спроектирован. Номинальная мини-колба не должна касаться чашки; нагрев и зазоры измерить на физическом образце.\n\nОПТИКА: поле не бесконечно: чашка даёт полностью освещённый радиус примерно${d.sourceAperture.fieldFullRadius.toFixed(1)}мм и полностью обрезает свет после${d.sourceAperture.fieldZeroRadius.toFixed(1)}мм. Совпадение силуэта ${(q.iou*100).toFixed(1)}% рассчитывается внутри этого поля; тёмный фон за полем не выдаётся за тень рисунка. Доля целевого силуэта вне поля${(q.targetUnlitFraction*100).toFixed(2)}%. Вся опора, крышка, проводка и крепёж включены в трассировку. Это не гарантия совпадения с художественной фотографией коллажа и не физическое испытание. Стекло, отражения, нагрев, удержание винтов и прочность пока не подтверждены.\n`;} 
export function conceptHTML(d){return `<h2>Дизайн №1 · реальная печатная сборка</h2><p>Чёрный непрозрачный диск, золотистые обод и рельефная розетка. Лампа смотрит к стене, плата и патрон стоят в съёмной передней крышке. Старый нижний кронштейн и центральная стойка удалены.</p><div class="service-grid"><figure><img src="assets/service/match-assembly.png" alt="Сборка согласованного дизайна"><figcaption>Геометрия из того же STL-комплекта.</figcaption></figure><figure><img src="assets/service/match-wiring.png" alt="Внутренняя проводка"><figcaption>Проводники идут по тёмному материалу и верхней опоре.</figcaption></figure></div><p>Для доступа к двум M2×8 крышки нужно снять светильник со стены и открыть задний доступ; плата E10 — с двух M2×4. Верхние опоры сварены с оболочкой. Подвес и нижний фиксатор находятся на задней панели.</p><p>Золотистые элементы не формируют тень. Надпись не выбрана и не включена в модель.</p><p class="hint">Чашка физически ограничивает круг света; силуэт сравнивается внутри освещённого поля. Внешний ореол может отличаться от художественного коллажа. Ширина короткого оптического перешейка0.8мм: нужны пробная печать, проверка поддержек и прочности. Размеры покупных деталей, нагрев и реальная оптика ещё не испытаны.</p>`;}
